+package prompt
+
+import (
+	"fmt"
+	"strings"
+	"unicode/utf8"
+)
+
+// linkedIssueHeadlineMaxRunes caps the first-sentence summary of a linked
+// issue's body.
+const linkedIssueHeadlineMaxRunes = 160
+
+// linkedIssueHeadline is the one-line summary of a linked issue the prompt
+// header lists: "#<n> <title>: <first sentence of body>".
+func linkedIssueHeadline(li LinkedIssue) string {
+	title := strings.Join(strings.Fields(li.Title), " ")
+	return fmt.Sprintf("#%d %s: %s", li.Number, title, firstSentence(li.Body, linkedIssueHeadlineMaxRunes))
+}
+
+// firstSentence returns s up to and including its first sentence end
+// (". ", "? ", "! " or a newline), whitespace-collapsed and cut at max runes.
+func firstSentence(s string, max int) string {
+	s = strings.TrimSpace(s)
+	end := len(s)
+	for _, sep := range []string{". ", "? ", "! ", "\n"} {
+		if i := strings.Index(s, sep); i >= 0 && i+1 < end {
+			end = i + 1
+		}
+	}
+	out := strings.Join(strings.Fields(s[:end]), " ")
+	if utf8.RuneCountInString(out) > max {
+		out = string([]rune(out)[:max])
+	}
+	return out
+}
