+++ b/backend/internal/prompt/linkedissue_test.go
@@ -0,0 +1,33 @@
+package prompt
+
+import (
+	"strings"
+	"testing"
+)
+
+func TestFirstSentence(t *testing.T) {
+	for _, tc := range []struct{ in, want string }{
+		{"Retry part uploads. Then log them.", "Retry part uploads."},
+		{"Why does it hang? It waits on a lock.", "Why does it hang?"},
+		{"one line\nsecond line", "one line"},
+		{"  no end at all  ", "no end at all"},
+	} {
+		if got := firstSentence(tc.in, linkedIssueHeadlineMaxRunes); got != tc.want {
+			t.Errorf("firstSentence(%q) = %q, want %q", tc.in, got, tc.want)
+		}
+	}
+	long := strings.Repeat("a", 400)
+	if got := firstSentence(long, linkedIssueHeadlineMaxRunes); len([]rune(got)) != linkedIssueHeadlineMaxRunes {
+		t.Errorf("long body cut to %d runes, want %d", len([]rune(got)), linkedIssueHeadlineMaxRunes)
+	}
+}
+
+func TestLinkedIssueHeadline(t *testing.T) {
+	li := LinkedIssue{Number: 812, Title: "Depends on\nthe store", Body: "Move the store first. Then the API."}
+	if got, want := linkedIssueHeadline(li), "#812 Depends on the store: Move the store first."; got != want {
+		t.Errorf("headline = %q, want %q", got, want)
+	}
+}
